llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Omadacycline absolute oral bioavailability in healthy adults is 34.5%, directly above the 20% threshold; this is the highest-transfer analogue and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "CGP 43371 oral bioavailability was 9% in healthy men after an 800-mg oral dose, below the threshold; this is the main contradictory evidence, though with lower transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C73"],
      "claim": "Hydrocortisone absolute oral bioavailability is high (88-93%) in healthy volunteers, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "9-Aminocamptothecin oral bioavailability was 49% ± 18 in patients, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Dihydroartemisinin absolute oral bioavailability was 45% (34-56%) in volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ixabepilone absolute oral bioavailability was 36.6-41.3% in patients, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Etoposide absolute oral bioavailability was approximately 50% in patients, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Erythromycin absolute oral bioavailability was 32 ± 7% in healthy subjects, above the threshold despite variable reports.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Idarubicin absolute oral bioavailability was 29% (range 12-49%) in patients, above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, led by the highest-transfer omadacycline (F=34.5%) and supported by multiple absolute oral bioavailability values of 29-93% across diverse complex natural-product-like scaffolds, supports F >=20%. The single strong low-F analogue (CGP 43371, 9%) is outweighed by the larger, higher-transfer supportive set.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The query's aqueous solubility and metabolic stability are not directly evidenced; the low-F analogue CGP 43371 was limited by poor solubility.",
    "Several supportive records are formulation-dependent or from different chemical classes, so quantitative F may not translate exactly."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

